const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '电源' },
      { kind: 'text', payload: '开关' },
      { kind: 'text', payload: '灯泡' },
      { kind: 'text', payload: '电流表' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 640;
    var H = (input && input.viewport && input.viewport.heightDu) || 420;
    var rev = input && input.revision;
    var s = visualSdk;
    var lm = metrics || [];

    var paths = [
      { id: 'wLeftTop', commands: s.polyline([{ x: 160, y: 130 }, { x: 160, y: 200 }]) },
      { id: 'wLeftBottom', commands: s.polyline([{ x: 160, y: 222 }, { x: 160, y: 310 }]) },
      { id: 'plateLong', commands: s.polyline([{ x: 138, y: 200 }, { x: 182, y: 200 }]) },
      { id: 'plateShort', commands: s.polyline([{ x: 147, y: 222 }, { x: 173, y: 222 }]) },
      { id: 'wTopLeft', commands: s.polyline([{ x: 160, y: 130 }, { x: 270, y: 130 }]) },
      { id: 'wTopRight', commands: s.polyline([{ x: 370, y: 130 }, { x: 480, y: 130 }]) },
      { id: 'switchBlade', commands: s.polyline([{ x: 270, y: 130 }, { x: 355, y: 105 }]) },
      { id: 'switchDotA', commands: s.circle(270, 130, 4) },
      { id: 'switchDotB', commands: s.circle(370, 130, 4) },
      { id: 'wRightTop', commands: s.polyline([{ x: 480, y: 130 }, { x: 480, y: 196 }]) },
      { id: 'wRightBottom', commands: s.polyline([{ x: 480, y: 244 }, { x: 480, y: 310 }]) },
      { id: 'bulbRing', commands: s.circle(480, 220, 24) },
      { id: 'bulbCrossA', commands: s.polyline([{ x: 463, y: 203 }, { x: 497, y: 237 }]) },
      { id: 'bulbCrossB', commands: s.polyline([{ x: 497, y: 203 }, { x: 463, y: 237 }]) },
      { id: 'wBottomLeft', commands: s.polyline([{ x: 160, y: 310 }, { x: 296, y: 310 }]) },
      { id: 'wBottomRight', commands: s.polyline([{ x: 344, y: 310 }, { x: 480, y: 310 }]) },
      { id: 'meterRing', commands: s.circle(320, 310, 24) }
    ];

    var children = [
      { type: 'path', pathId: 'wLeftTop', stroke: '#26354a' },
      { type: 'path', pathId: 'wLeftBottom', stroke: '#26354a' },
      { type: 'path', pathId: 'plateLong', stroke: '#26354a' },
      { type: 'path', pathId: 'plateShort', stroke: '#26354a' },
      { type: 'path', pathId: 'wTopLeft', stroke: '#26354a' },
      { type: 'path', pathId: 'wTopRight', stroke: '#26354a' },
      { type: 'path', pathId: 'switchBlade', stroke: '#26354a' },
      { type: 'path', pathId: 'switchDotA', stroke: '#26354a', fill: '#26354a' },
      { type: 'path', pathId: 'switchDotB', stroke: '#26354a', fill: '#26354a' },
      { type: 'path', pathId: 'wRightTop', stroke: '#26354a' },
      { type: 'path', pathId: 'wRightBottom', stroke: '#26354a' },
      { type: 'path', pathId: 'bulbRing', stroke: '#26354a' },
      { type: 'path', pathId: 'bulbCrossA', stroke: '#26354a' },
      { type: 'path', pathId: 'bulbCrossB', stroke: '#26354a' },
      { type: 'path', pathId: 'wBottomLeft', stroke: '#26354a' },
      { type: 'path', pathId: 'wBottomRight', stroke: '#26354a' },
      { type: 'path', pathId: 'meterRing', stroke: '#26354a' },
      { type: 'label', text: '电源', x: 100, y: 218, fontSize: 20, anchor: 'middle', fill: '#26354a' },
      { type: 'label', text: '开关', x: 320, y: 78, fontSize: 20, anchor: 'middle', fill: '#26354a' },
      { type: 'label', text: '灯泡', x: 548, y: 228, fontSize: 20, anchor: 'middle', fill: '#26354a' },
      { type: 'label', text: '电流表', x: 320, y: 362, fontSize: 20, anchor: 'middle', fill: '#26354a' }
    ];

    if (lm.length === 0) { /* no text metrics returned; label positions use fixed anchors */ }

    return {
      schemaVersion: 1,
      sceneId: 'circuit-transcription',
      revision: rev,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
